def get_common_prefix(s1, s2):
    prefix = ""
    for c1, c2 in zip(s1, s2):
        if c1 == c2:
            prefix += c1
        else:
            break
    return prefix

def get_common_suffix(s1, s2):
    suffix = ""
    for c1, c2 in zip(reversed(s1), reversed(s2)):
        if c1 == c2:
            suffix = c1 + suffix
        else:
            break
    return suffix

